    "shortDesc": "Scorbutic anemia",
    "longDesc": "Scorbutic anemia",
    "plainEnglish": "Scorbutic anemia is a type of anemia (low red blood cell count) caused by severe vitamin C deficiency, a condition known as scurvy. This deficiency prevents your body from properly forming and maintaining healthy red blood cells, leading to fatigue, weakness, and shortness of breath. It typically develops in people with very poor nutrition who aren't eating enough vitamin C-rich foods like citrus fruits, berries, and leafy greens.",
    "whoUses": "This code is used by hematologists, primary care physicians, and hospitalists when diagnosing and treating severe nutritional anemia related to scurvy. It is relatively uncommon in developed countries and may appear on EOB statements when a patient has been evaluated for unexplained anemia with nutritional deficiency.",
