    "shortDesc": "Anemia due to glucose-6-phosphate dehydrogenase deficiency",
    "longDesc": "Anemia due to glucose-6-phosphate dehydrogenase [G6PD] deficiency",
    "plainEnglish": "G6PD deficiency is an inherited condition where your body lacks an enzyme called glucose-6-phosphate dehydrogenase that normally protects your red blood cells from damage. When you're exposed to certain triggers—like specific medications (such as sulfa drugs or antimalarials), fava beans, infections, or severe stress—your red blood cells can break down faster than your body can replace them, causing anemia (low red blood cell count). You might feel tired, short of breath, have jaundice (yellowing of skin), or notice dark urine during these episodes.",
    "whoUses": "Hematologists and primary care physicians use this code when diagnosing and managing patients with G6PD deficiency anemia, often after screening tests reveal the enzyme deficiency. It commonly appears on patient EOBs when laboratory testing, genetic counseling, or acute hemolytic episodes require medical evaluation and treatment.",
