    "plainEnglish": "Pyruvate kinase deficiency is a rare inherited blood disorder where your red blood cells don't produce enough of an enzyme called pyruvate kinase, which they need to generate energy and survive in your bloodstream. Without adequate enzyme activity, your red blood cells break down faster than normal, leading to anemia—a condition where you don't have enough healthy red blood cells to carry oxygen throughout your body. You might experience fatigue, shortness of breath, jaundice (yellowing of the skin and eyes), or dark urine.",
