    "shortDesc": "Alpha thalassemia",
    "longDesc": "Alpha thalassemia",
    "plainEnglish": "Alpha thalassemia is an inherited blood disorder where your body doesn't make enough of a protein called alpha-globin, which is a key component of hemoglobin (the protein in red blood cells that carries oxygen). This causes your red blood cells to be smaller and more fragile than normal, leading to anemia—meaning you don't have enough healthy red blood cells to carry oxygen throughout your body. People with alpha thalassemia may experience fatigue, shortness of breath, jaundice (yellowing of the skin), and may require regular blood transfusions or other treatments depending on how severe the condition is.",
    "whoUses": "Hematologists (blood specialists) and pediatricians most commonly diagnose and manage alpha thalassemia, often identifying it in childhood through routine blood work or when a patient presents with anemia symptoms. This code regularly appears on EOB statements for patients receiving ongoing care, blood transfusions, or genetic counseling related to this lifelong inherited condition.",
