    "plainEnglish": "Delta-beta thalassemia is a rare inherited blood disorder where your body doesn't make enough of two types of hemoglobin (the protein in red blood cells that carries oxygen). This happens because the genes that control production of delta and beta globin chains are defective or missing. People with this condition may experience anemia symptoms like fatigue, shortness of breath, and pale skin, though symptoms can range from mild to severe depending on whether they inherited the faulty gene from one or both parents.",
