    "longDesc": "Hb-SS disease with crisis, unspecified",
    "plainEnglish": "This code describes sickle cell disease (specifically the most severe type where you inherit the sickle cell gene from both parents) during an acute crisis. A sickle cell crisis occurs when misshapen red blood cells block blood vessels, causing sudden severe pain, organ damage, and potentially life-threatening complications. Patients in crisis typically experience intense pain in bones or joints, shortness of breath, chest pain, or stroke symptoms and require emergency hospital care.",
    "whoUses": "Hematologists, emergency medicine doctors, and hospitalists use this code when treating patients with sickle cell disease experiencing an acute crisis. It commonly appears on hospital bills and EOB statements because sickle cell crises typically require emergency department visits or inpatient admission.",
