    "longDesc": "Hb-SS disease with splenic sequestration",
    "plainEnglish": "This code describes a serious complication of sickle cell disease (the most severe form, caused by two copies of the sickle cell gene) where your spleen becomes enlarged and traps large amounts of your red blood cells, causing them to get stuck there instead of circulating normally. This can happen suddenly and cause severe anemia, weakness, and a dangerously enlarged spleen that requires urgent medical attention. Without treatment, this life-threatening complication can lead to severe organ damage or shock.",
    "whoUses": "Hematologists and emergency medicine physicians use this code when a patient with sickle cell disease (Hb-SS) presents with acute splenic sequestration. This diagnosis commonly appears on EOB statements for patients receiving inpatient hospital care or emergency department treatment for this acute sickle cell complication, as it typically requires immediate hospitalization and blood transfusions.",
