    "shortDesc": "Hb-SS disease with cerebral vascular involvement",
    "longDesc": "Hb-SS disease with cerebral vascular involvement",
    "plainEnglish": "This code describes sickle cell disease (specifically the most severe form where you have two copies of the sickle cell gene) that has caused a stroke or blood vessel problem in the brain. In sickle cell disease, red blood cells become rigid and crescent-shaped, which can block blood vessels and reduce oxygen flow to organs—in this case, affecting blood flow to the brain. People with this condition have experienced a serious complication where abnormal blood clotting or vessel blockage has damaged brain tissue, which can result in stroke symptoms like weakness, speech problems, or other neurological effects.",
    "whoUses": "Hematologists, neurologists, and emergency medicine physicians use this code when diagnosing and treating sickle cell patients who develop stroke complications. This code commonly appears on EOB statements for patients with sickle cell disease who have had imaging studies (MRI/CT scans), hospital admissions, or specialist consultations related to neurological complications.",
