    "rawCode": "D57212",
    "shortDesc": "Sickle-cell/Hb-C disease with splenic sequestration",
    "longDesc": "Sickle-cell/Hb-C disease with splenic sequestration",
    "plainEnglish": "This diagnosis means you have a combination of sickle cell disease and hemoglobin C disease (two inherited blood disorders), and your spleen is trapping large numbers of red blood cells, causing it to become enlarged and painful. When red blood cells get stuck in the spleen, they can't circulate properly through your body, which can lead to anemia, weakness, and a swollen, tender spleen. This is a serious complication that requires medical attention because it can develop quickly and cause severe symptoms.",
    "whoUses": "Hematologists and primary care physicians use this code when managing patients with sickle cell disease complications. It commonly appears on EOB statements for patients with known sickle cell disease who develop acute splenic crises or complications requiring hospital admission or emergency care.",
