    "longDesc": "Sickle-cell/Hb-C disease with cerebral vascular involvement",
    "plainEnglish": "This code indicates sickle-cell disease combined with hemoglobin C disease (a rare inherited blood condition where someone inherits one sickle cell gene and one hemoglobin C gene), and the patient has experienced a stroke or other blood vessel problem in the brain as a result. The abnormal red blood cells are blocking blood flow to the brain, which can cause serious complications like strokes, transient ischemic attacks (mini-strokes), or other neurological damage.",
    "whoUses": "Hematologists, neurologists, and emergency medicine specialists use this code when a patient with sickle-cell/Hb-C disease presents with acute stroke or cerebrovascular events. This code commonly appears on EOB statements for patients hospitalized with stroke or requiring imaging and specialist consultations related to this complication.",
