    "rawCode": "D57214",
    "shortDesc": "Sickle-cell/Hb-C disease with dactylitis",
    "longDesc": "Sickle-cell/Hb-C disease with dactylitis",
    "plainEnglish": "This code describes a type of sickle cell disease where a person has inherited both the sickle cell trait and hemoglobin C (an abnormal form of hemoglobin), and they are currently experiencing dactylitis—severe pain and swelling in the hands and feet caused by small blood vessels getting blocked by sickled red blood cells. Dactylitis, sometimes called \"hand-foot syndrome,\" is often one of the first painful complications of sickle cell disease and typically occurs in infants and young children.",
    "whoUses": "Hematologists, primary care physicians, pediatricians, and emergency medicine doctors use this code when treating patients with sickle-cell/Hb-C disease who present with acute hand or foot swelling and pain. This code commonly appears on EOB statements for children and young adults with sickle cell disease during acute care visits or hospitalizations for pain crisis management.",
