    "plainEnglish": "This diagnosis means you have a combination of two abnormal hemoglobin types (sickle-cell and Hemoglobin C) that cause your red blood cells to become rigid and block blood vessels, leading to a serious acute crisis with an additional specific health problem beyond the typical pain and organ damage. During a sickle-cell/Hb-C crisis, you may experience severe pain, fever, swelling, and potentially damage to organs like the lungs, kidneys, or liver, depending on which complication is occurring.",
    "whoUses": "Hematologists, emergency medicine physicians, and hospitalists use this code when treating patients with sickle-cell disease variant during acute exacerbations. This code commonly appears on EOB statements for patients admitted to the hospital for crisis management and is used to justify the complexity and severity of inpatient care.",
