    "shortDesc": "Sickle-cell trait",
    "longDesc": "Sickle-cell trait",
    "plainEnglish": "Sickle-cell trait means you carry one gene for sickle cell disease, but you don't have the full disease itself. Your red blood cells are mostly normal, though some may occasionally sickle under extreme stress (like intense exercise at high altitude or severe dehydration), and you typically won't experience symptoms. This is different from sickle-cell disease, where you inherit two sickle-cell genes and have chronic, painful episodes.",
    "whoUses": "Primary care physicians, hematologists, and genetic counselors commonly document this code during routine screening, family history assessment, or genetic testing. It appears on EOBs when patients undergo hemoglobin electrophoresis or genetic screening, though it's typically noted for informational and counseling purposes rather than for acute treatment.",
