    "plainEnglish": "You have a genetic blood disorder where your red blood cells contain both sickle cell and thalassemia beta zero mutations, meaning your body doesn't make normal hemoglobin. This combination causes your red blood cells to be fragile and misshapen, but you are currently not experiencing an acute crisis (a sudden, painful flare-up). Over time, this condition can lead to anemia, organ damage, and pain, though the severity varies greatly from person to person.",
    "whoUses": "Hematologists (blood specialists) primarily use this code when managing patients with this rare genetic blood disorder, often in specialty clinics focused on hemoglobinopathies. It appears on EOB statements when patients receive monitoring blood work, genetic counseling, or preventive care visits but are not being treated for an active crisis.",
