    "whoUses": "Hematologists, internal medicine physicians, and pediatricians use this code when managing patients with this combined genetic blood disorder, particularly during acute episodes of splenic sequestration. This code commonly appears on EOB statements for patients with known sickle-cell thalassemia disease who develop complications requiring hospitalization or specialized care.",
