    "shortDesc": "Hereditary elliptocytosis",
    "longDesc": "Hereditary elliptocytosis",
    "plainEnglish": "Hereditary elliptocytosis is an inherited blood disorder where your red blood cells are abnormally shaped like ovals or ellipses instead of the normal round disk shape. This shape abnormality makes the red blood cells more fragile and prone to breaking down faster than normal, which can lead to anemia (low red blood cell count), fatigue, jaundice (yellowing of skin and eyes), and sometimes gallstones. The condition is passed down through families and is caused by defects in the proteins that form the outer membrane of red blood cells.",
