    "longDesc": "Hereditary hemolytic anemia, unspecified",
    "plainEnglish": "This code describes an inherited condition where red blood cells break down faster than normal (hemolysis), but the specific type of hereditary anemia hasn't been identified or documented. Your body may not have enough healthy red blood cells because they're being destroyed prematurely, which can cause fatigue, weakness, jaundice (yellowing of skin and eyes), and pale skin. While doctors know this is a genetic condition passed down through your family, they haven't pinpointed whether it's due to a problem with the cell membrane, abnormal hemoglobin, or enzyme deficiencies.",
