    "rawCode": "D5913",
    "shortDesc": "Mixed type autoimmune hemolytic anemia",
    "longDesc": "Mixed type autoimmune hemolytic anemia",
    "plainEnglish": "Mixed type autoimmune hemolytic anemia is a condition where your immune system mistakenly attacks your red blood cells, causing them to break down faster than your body can replace them. This particular type involves multiple different antibodies attacking your red cells simultaneously, which makes it more complex and harder to treat than other forms. You might experience fatigue, shortness of breath, jaundice (yellowing of skin), dark urine, or paleness as your body struggles with the reduced number of healthy red blood cells.",
    "whoUses": "Hematologists (blood specialists) and internal medicine doctors most commonly diagnose and manage this condition, often after testing shows positive results on both direct and indirect Coombs tests. This code does appear on EOB statements when patients receive inpatient or outpatient treatment, including transfusions, immunosuppressive therapy, or monitoring for this autoimmune blood disorder.",
