    "shortDesc": "Other autoimmune hemolytic anemia",
    "longDesc": "Other autoimmune hemolytic anemia",
    "plainEnglish": "Your immune system is mistakenly attacking and destroying your red blood cells, causing a type of anemia called autoimmune hemolytic anemia. This happens when your body produces antibodies that treat your own red blood cells as foreign invaders, breaking them down faster than your body can replace them. You might feel tired, weak, short of breath, or have jaundice (yellowing of skin and eyes) because your body doesn't have enough healthy red blood cells to carry oxygen effectively.",
    "whoUses": "Hematologists and internal medicine physicians commonly diagnose and treat this condition, and it may also be managed by rheumatologists if it's associated with an underlying autoimmune disease. This code appears on patient EOBs when billing for office visits, lab work (like blood tests showing hemolysis), or treatments for autoimmune hemolytic anemia.",
