    "shortDesc": "Hemolytic-uremic syndrome, unspecified",
    "longDesc": "Hemolytic-uremic syndrome, unspecified",
    "plainEnglish": "Hemolytic-uremic syndrome (HUS) is a serious condition where your body's red blood cells are destroyed faster than normal, and your kidneys stop working properly. This usually develops after a severe diarrheal infection (often from contaminated food or water) and causes symptoms like bloody stools, anemia, low platelet counts, and kidney failure. The \"unspecified\" part means the specific cause or trigger hasn't been identified in your medical records.",
    "whoUses": "Nephrologists, pediatricians, and emergency medicine physicians use this code when diagnosing and treating HUS, which occurs most commonly in young children and can appear on EOB statements related to hospitalization, dialysis, or intensive care management. It's frequently seen in referrals between hospitals and specialized kidney centers.",
