    "code": "D59.31",
    "rawCode": "D5931",
    "shortDesc": "Infection-associated hemolytic-uremic syndrome",
    "longDesc": "Infection-associated hemolytic-uremic syndrome",
    "plainEnglish": "Infection-associated hemolytic-uremic syndrome (HUS) is a serious condition where a bacterial infection (often from contaminated food or water) damages your blood vessels and causes your red blood cells to break down, leading to anemia, kidney failure, and low platelet counts that affect your blood's ability to clot. This typically happens after you've had severe diarrhea or other gastrointestinal symptoms, and it's a medical emergency that requires hospitalization and close monitoring of kidney function. Symptoms can include bloody diarrhea, severe abdominal pain, pale skin, decreased urination, and easy bruising.",
    "whoUses": "Nephrologists, infectious disease specialists, and critical care physicians commonly diagnose and treat HUS, often in hospital settings. This code appears on EOB statements when patients are hospitalized for acute kidney injury and multi-organ complications following a bacterial infection, typically caused by Shiga toxin-producing E. coli or similar pathogens.",
