    "shortDesc": "Hereditary hemolytic-uremic syndrome",
    "longDesc": "Hereditary hemolytic-uremic syndrome",
    "plainEnglish": "Hereditary hemolytic-uremic syndrome is a rare genetic condition where your body's immune system mistakenly attacks and destroys red blood cells, while also damaging small blood vessels in your kidneys, leading to anemia, bruising, and kidney problems. Unlike the more common acquired form triggered by infections, this version runs in families because of an inherited gene mutation that makes your body unable to properly regulate this harmful immune response. Patients typically experience fatigue, bleeding or bruising, and may have reduced kidney function that requires close monitoring.",
    "whoUses": "Nephrologists, hematologists, and pediatricians use this code when diagnosing and managing patients with the genetic form of hemolytic-uremic syndrome, particularly in children with a family history of the condition. It is less common on patient EOBs compared to other hemolytic anemias, as it is a rare inherited disorder, but will appear when genetic testing confirms the hereditary form or when managing complications in known affected families.",
