    "plainEnglish": "This code describes a rare kidney and blood disorder called hemolytic-uremic syndrome (HUS) that doesn't fit the more common types. In this condition, your red blood cells are destroyed prematurely, your kidneys are damaged, and you may develop low platelet counts, which can cause bleeding problems and kidney failure. Patients typically experience symptoms like severe diarrhea, kidney pain, low urine output, and bruising, often triggered by a bacterial infection (particularly E. coli).",
    "whoUses": "Nephrologists (kidney specialists), hematologists, and critical care physicians use this code when diagnosing and treating atypical HUS cases. While HUS is a serious condition requiring hospitalization, this specific code appears less frequently on patient EOBs since most HUS cases are classified under more specific subtypes; however, it will appear when the HUS presentation doesn't match the typical Shiga toxin-producing E. coli variant.",
