    "plainEnglish": "Paroxysmal nocturnal hemoglobinuria (PNH) is a rare blood disorder where your red blood cells are destroyed by your immune system, especially at night or during certain times. This happens because your bone marrow produces blood cells that lack protective proteins, making them vulnerable to attack. Patients typically experience dark urine (which contains hemoglobin from destroyed red blood cells), fatigue, shortness of breath, and sometimes blood clots.",
    "whoUses": "Hematologists and oncologists diagnose and manage PNH, often using specialized flow cytometry tests. This code appears on EOB statements when patients receive evaluation, diagnosis, or treatment for this serious hemolytic anemia, including appointments for monitoring or infusions of complement inhibitor medications.",
