    "rawCode": "D596",
    "shortDesc": "Hemoglobinuria due to hemolysis from other external causes",
    "longDesc": "Hemoglobinuria due to hemolysis from other external causes",
    "plainEnglish": "Hemoglobinuria due to hemolysis from other external causes occurs when red blood cells break down (hemolysis) from something outside the body—like extreme temperature exposure, severe burns, crush injuries, or transfusion reactions—causing hemoglobin (the protein that carries oxygen in blood) to be released into the urine, which turns it dark or cola-colored. This happens because the damaged red blood cells leak their contents into the bloodstream, and the kidneys filter out the excess hemoglobin into the urine. You might notice dark urine, fatigue, shortness of breath, or jaundice if the breakdown is severe.",
    "whoUses": "Emergency medicine physicians, trauma surgeons, intensive care specialists, and hematologists use this code when treating patients with severe external injuries or conditions causing rapid red blood cell destruction. It appears less frequently on routine EOB statements since it typically indicates acute, serious conditions requiring hospitalization rather than outpatient care.",
