    "code": "D60.1",
    "rawCode": "D601",
    "shortDesc": "Transient acquired pure red cell aplasia",
    "longDesc": "Transient acquired pure red cell aplasia",
    "plainEnglish": "Transient acquired pure red cell aplasia is a temporary condition where your bone marrow stops making red blood cells, even though it continues to produce white blood cells and platelets normally. This can happen suddenly in response to a viral infection, medication, or immune system issue, and it causes anemia (low red blood cell count) with symptoms like fatigue, shortness of breath, and pale skin. The good news is that this condition is temporary—your bone marrow typically recovers on its own and returns to normal red blood cell production within weeks to months.",
    "whoUses": "Hematologists (blood specialists) and internal medicine physicians diagnose and manage this condition, often identified through blood tests and bone marrow evaluation. While it can appear on patient EOB statements, it's more commonly documented in hospital or specialist office visit records rather than as a primary diagnosis on routine insurance claims.",
