    "longDesc": "Constitutional (pure) red blood cell aplasia",
    "plainEnglish": "This is a rare condition where your bone marrow fails to produce red blood cells, even though your white blood cells and platelets may be normal. This happens because of a genetic or developmental problem present from birth, meaning your body was born with this defect rather than acquiring it later in life. Without enough red blood cells, you may experience severe fatigue, shortness of breath, and weakness because your body isn't getting enough oxygen.",
