    "code": "D61.02",
    "rawCode": "D6102",
    "shortDesc": "Shwachman-Diamond syndrome",
    "longDesc": "Shwachman-Diamond syndrome",
    "plainEnglish": "Shwachman-Diamond syndrome is a rare inherited genetic disorder that affects bone marrow's ability to produce blood cells, leading to low counts of white blood cells, red blood cells, and platelets. People with this condition often experience frequent infections (due to low white blood cells), fatigue and anemia (from low red blood cells), and easy bruising or bleeding (from low platelets). The syndrome is typically diagnosed in childhood and may also affect the pancreas, causing difficulty with fat digestion and nutrient absorption.",
    "whoUses": "Hematologists and pediatricians most commonly diagnose and manage Shwachman-Diamond syndrome, often with support from genetic counselors and gastroenterologists. This code appears relatively infrequently on patient EOBs since it's a rare genetic condition, but when it does appear, it's typically associated with ongoing specialist care and blood work monitoring.",
