    "shortDesc": "Fanconi anemia",
    "longDesc": "Fanconi anemia",
    "plainEnglish": "Fanconi anemia is a rare inherited blood disorder where your bone marrow doesn't make enough healthy blood cells, leading to anemia (low red blood cells), increased infections (due to low white blood cells), and easy bleeding or bruising (due to low platelets). People born with this condition have defective DNA repair genes, which also significantly increases their risk of developing certain cancers, particularly leukemia and solid tumors, often at a younger age than typical.",
    "whoUses": "Hematologists, oncologists, and pediatricians use this code when diagnosing and managing Fanconi anemia patients. It commonly appears on EOB statements for patients undergoing bone marrow evaluation, genetic testing, blood transfusions, or cancer screening related to this inherited condition.",
