    "longDesc": "Drug-induced aplastic anemia",
    "plainEnglish": "Drug-induced aplastic anemia means that a medication you took has damaged your bone marrow, preventing it from making enough red blood cells, white blood cells, and platelets. This causes severe anemia (low red blood cells), increased infections (low white blood cells), and easy bruising or bleeding (low platelets). Certain drugs like chemotherapy, some antibiotics, NSAIDs, or anticonvulsants are known to trigger this serious condition.",
    "whoUses": "Hematologists, oncologists, and emergency medicine physicians use this code when a patient's bone marrow failure is directly linked to a medication exposure. It commonly appears on EOB statements when patients require hospitalization, transfusions, or bone marrow testing to evaluate medication-related bone marrow damage.",
