    "shortDesc": "Antineoplastic chemotherapy induced pancytopenia",
    "longDesc": "Antineoplastic chemotherapy induced pancytopenia",
    "plainEnglish": "Pancytopenia is a condition where your bone marrow doesn't make enough of all three types of blood cells (red cells, white cells, and platelets), and in this case it was caused by chemotherapy drugs used to treat cancer. This side effect means you may feel tired and weak (from low red blood cells), get infections more easily (from low white blood cells), and bruise or bleed more easily (from low platelets). The good news is that this condition often improves after chemotherapy is completed, though it may require close monitoring and sometimes treatment to support your blood cell counts.",
    "whoUses": "Oncologists and hematologists use this code during and after cancer treatment to document chemotherapy side effects. It commonly appears on EOB statements for patients receiving active cancer treatment, as insurance companies need to track this expected but serious complication.",
