    "longDesc": "Other pancytopenia",
    "plainEnglish": "Pancytopenia means your bone marrow isn't making enough of all three types of blood cells (red cells for oxygen, white cells for infection-fighting, and platelets for clotting) at the same time. This code is used when the cause doesn't fit neatly into the more common categories—it might result from medications, toxins, autoimmune conditions, or other underlying disorders. You might feel unusually tired, get infections more easily, or bruise and bleed more readily than normal.",
    "whoUses": "Hematologists (blood specialists), oncologists, and internal medicine doctors use this code when evaluating patients with persistent low blood cell counts from causes like drug reactions, certain infections, or autoimmune diseases. It appears on EOBs when patients undergo bone marrow biopsies, blood transfusions, or treatment for the underlying cause of their low blood counts.",
