    "longDesc": "Myelophthisis",
    "plainEnglish": "Myelophthisis occurs when abnormal tissue—such as scar tissue, cancer, fibrosis, or other pathological material—invades and replaces the healthy bone marrow, preventing it from producing adequate blood cells. This leads to anemia (low red blood cells), infections (low white blood cells), and bleeding problems (low platelets), as your body loses its factory for making blood. You might feel tired, get infections more easily, or bruise and bleed more readily than normal.",
    "whoUses": "Hematologists (blood specialists) and oncologists (cancer doctors) use this code when diagnosing bone marrow failure caused by infiltration or replacement of marrow tissue by fibrosis, malignancy, or other pathologic processes. This code appears on EOB statements when patients undergo bone marrow biopsy or are hospitalized for evaluation and treatment of bone marrow failure.",
