    "rawCode": "D6189",
    "shortDesc": "Oth aplastic anemias and other bone marrow failure syndromes",
    "longDesc": "Other specified aplastic anemias and other bone marrow failure syndromes",
    "plainEnglish": "This code describes a rare condition where your bone marrow fails to produce enough blood cells, leading to aplastic anemia or another bone marrow disorder that doesn't fit neatly into standard categories. Your bone marrow is the spongy tissue inside your bones that normally makes red blood cells, white blood cells, and platelets; when it stops working properly, you may experience fatigue, infections, or easy bruising. This diagnosis typically follows extensive testing and is used when a patient has confirmed bone marrow failure but has an unusual or less common variant of the condition.",
    "whoUses": "Hematologists (blood specialists) and oncologists most commonly use this code when documenting rare or atypical cases of aplastic anemia in hospital or specialty clinic settings. It appears on EOB statements when patients undergo bone marrow biopsies, transfusions, or specialized treatments for blood disorders that require careful medical management and follow-up.",
