    "shortDesc": "Aplastic anemia, unspecified",
    "longDesc": "Aplastic anemia, unspecified",
    "plainEnglish": "Aplastic anemia means your bone marrow isn't producing enough blood cells of all types—red cells (causing fatigue and weakness), white cells (increasing infection risk), and platelets (causing easy bleeding or bruising). This is a serious condition where the bone marrow essentially fails or shuts down, and when doctors can't identify a specific cause, they use this 'unspecified' code. You may experience severe fatigue, shortness of breath, frequent infections, or abnormal bleeding depending on which cell counts are most affected.",
    "whoUses": "Hematologists (blood specialists) and oncologists primarily diagnose and manage aplastic anemia, often ordering bone marrow biopsies to confirm the diagnosis. This code commonly appears on patient EOBs when bone marrow testing, transfusions, or specialist consultations occur, and may indicate the need for further workup to determine the underlying cause.",
