    "shortDesc": "Anemia in neoplastic disease",
    "longDesc": "Anemia in neoplastic disease",
    "plainEnglish": "This code describes a type of anemia (low red blood cell count) that develops as a result of cancer or a tumor in your body. Cancer can cause anemia in several ways—it may affect your bone marrow's ability to produce red blood cells, cause chronic bleeding, or trigger inflammation that interferes with normal blood cell production. Patients with this condition typically experience fatigue, shortness of breath, and weakness due to the reduced oxygen-carrying capacity of their blood.",
    "whoUses": "Oncologists, hematologists, and internal medicine physicians use this code when treating cancer patients who develop anemia as a secondary effect of their malignancy. It commonly appears on EOBs for patients undergoing cancer treatment, as anemia management (including transfusions or medications like erythropoiesis-stimulating agents) is often necessary during cancer care.",
