    "shortDesc": "Anemia in chronic kidney disease",
    "longDesc": "Anemia in chronic kidney disease",
    "plainEnglish": "Anemia in chronic kidney disease means you have a low red blood cell count caused by long-term kidney problems. Your kidneys normally produce a hormone called erythropoietin that signals your bone marrow to make red blood cells, but when your kidneys are damaged and not working well, they can't produce enough of this hormone, leading to fewer red blood cells and less oxygen being carried throughout your body. You might feel tired, weak, shortness of breath, or notice pale skin as a result of this low red blood cell count.",
    "whoUses": "Nephrologists (kidney specialists), primary care physicians, and cardiologists commonly use this code when managing patients with chronic kidney disease. It frequently appears on EOB statements for patients with Stage 3-5 CKD who are being treated with medications like erythropoiesis-stimulating agents (ESAs) or iron supplements.",
