    "longDesc": "Hereditary sideroblastic anemia",
    "plainEnglish": "Hereditary sideroblastic anemia is a rare inherited blood disorder where your bone marrow cannot properly use iron to make healthy red blood cells, causing iron to accumulate abnormally in the cells instead. This leads to a shortage of functioning red blood cells (anemia), which means your body doesn't carry enough oxygen, leaving you fatigued, short of breath, or pale. The condition is passed down through families due to genetic mutations and typically appears in childhood or early adulthood.",
