    "code": "D65",
    "rawCode": "D65",
    "shortDesc": "Disseminated intravascular coagulation",
    "longDesc": "Disseminated intravascular coagulation [defibrination syndrome]",
    "plainEnglish": "Disseminated intravascular coagulation (DIC) is a serious condition where your blood clotting system goes into overdrive throughout your entire body, causing excessive clots to form in small blood vessels while simultaneously using up platelets and clotting factors. This paradoxical state leads to both widespread clotting and uncontrolled bleeding at the same time, which can damage organs and cause life-threatening hemorrhaging. DIC is not a primary disease itself but rather a complication of severe underlying illnesses such as sepsis, severe trauma, cancer, or obstetric emergencies.",
    "whoUses": "Hematologists, critical care physicians, and emergency medicine doctors commonly diagnose and manage DIC in intensive care settings. While DIC represents a serious inpatient condition, patients may see this code on EOB statements if they were hospitalized for treatment of the underlying triggering condition, as DIC itself requires hospital-level intervention and monitoring.",
    "billable": true,
    "isNew": false,
    "isRevised": false,
    "chapterId": 3,
