    "rawCode": "D66",
    "shortDesc": "Hereditary factor VIII deficiency",
    "longDesc": "Hereditary factor VIII deficiency",
    "plainEnglish": "Hereditary factor VIII deficiency, commonly known as hemophilia A, is an inherited bleeding disorder where your body doesn't make enough of a blood-clotting protein called factor VIII. This means your blood doesn't clot normally, so you may experience excessive bleeding from minor cuts, easy bruising, or spontaneous bleeding into joints and muscles. The condition is passed down through families and is usually diagnosed in childhood, though severity can vary widely from person to person.",
    "whoUses": "Hematologists (blood specialists), hemophilia treatment centers, and emergency medicine physicians use this code most frequently. It commonly appears on EOB statements for patients receiving clotting factor infusions, specialty pharmacy services, and regular monitoring appointments.",
