    "rawCode": "D67",
    "shortDesc": "Hereditary factor IX deficiency",
    "longDesc": "Hereditary factor IX deficiency",
    "plainEnglish": "Hereditary factor IX deficiency, also known as Christmas disease or hemophilia B, is an inherited bleeding disorder where your body doesn't produce enough of a protein (factor IX) needed to form blood clots properly. People with this condition experience prolonged bleeding after injuries, spontaneous bruising, and may have bleeding into joints or muscles, with severity ranging from mild to severe depending on how much factor IX is present.",
    "whoUses": "Hematologists and hemophilia specialists diagnose and manage this condition, and it may also be seen by emergency medicine physicians, orthopedists (for joint bleeding), and primary care doctors. This code appears on EOBs for patients undergoing genetic testing, factor IX replacement therapy, or treatment of bleeding complications related to this inherited condition.",
