    "shortDesc": "Von Willebrand disease, unspecified",
    "longDesc": "Von Willebrand disease, unspecified",
    "plainEnglish": "Von Willebrand disease is an inherited bleeding disorder where your blood doesn't clot as well as it should because you're missing or have low levels of a specific protein called von Willebrand factor. People with this condition may experience excessive bleeding from minor cuts, frequent nosebleeds, heavy menstrual periods, or easy bruising, though some people have very mild symptoms or none at all. The 'unspecified' part means your doctor has diagnosed you with this condition but hasn't yet determined which of the three main types you have.",
    "whoUses": "Hematologists (blood specialists) and primary care physicians commonly diagnose and manage von Willebrand disease. This code frequently appears on patient EOBs, particularly when associated with bleeding evaluations, genetic testing, or treatment with clotting factor replacements or medications like desmopressin.",
