    "plainEnglish": "Von Willebrand disease type 1 is a bleeding disorder where your body doesn't produce enough of a protein called von Willebrand factor, which helps your blood clot properly. This is the most common type of von Willebrand disease and typically causes mild to moderate symptoms like easy bruising, prolonged bleeding from cuts or nosebleeds, and heavy or prolonged menstrual periods in women. Most people with type 1 can manage their symptoms well with treatment and lifestyle adjustments.",
