    "longDesc": "Antiphospholipid antibody with hemorrhagic disorder",
    "plainEnglish": "This condition means you have proteins in your blood (antiphospholipid antibodies) that incorrectly attack your body's natural blood clotting factors, causing excessive bleeding or bruising. Instead of helping your blood clot normally, these antibodies interfere with the clotting process, which can lead to spontaneous bleeding, blood in your urine or stool, or prolonged bleeding from minor cuts. This is a serious autoimmune condition that requires careful monitoring and treatment to prevent dangerous bleeding episodes.",
    "whoUses": "Hematologists (blood specialists), rheumatologists, and internal medicine doctors diagnose and manage this condition, often in collaboration with anticoagulation specialists. This code appears on EOBs when patients are being evaluated or treated for bleeding complications related to antiphospholipid syndrome.",
