    "longDesc": "Hemorrhagic disorder due to extrinsic circulating anticoagulants",
    "plainEnglish": "This condition means your blood is not clotting properly because something in your bloodstream—usually a medication like warfarin or other blood thinners—is preventing normal clotting. You may experience excessive bleeding from minor cuts, bruising easily, nosebleeds, or other bleeding symptoms that seem unusual for a small injury. This diagnosis is especially important because it explains why your bleeding risk is higher than normal and helps guide your medical care.",
    "whoUses": "Hematologists, emergency medicine physicians, and primary care doctors use this code when evaluating patients on anticoagulant therapy who experience bleeding complications or have bleeding disorders related to these medications. This code appears on EOB statements for patients being treated with blood thinners or for those with bleeding complications related to anticoagulant use.",
