    "plainEnglish": "Your blood has a deficiency in one or more clotting factors that your body should normally make on its own. This means your blood doesn't clot as well as it should, which could happen because of liver disease, vitamin K deficiency, certain medications, or other acquired conditions—unlike a genetic bleeding disorder you're born with. You might experience excessive bruising, prolonged bleeding from cuts, or abnormal bleeding.",
    "whoUses": "Hematologists, internal medicine doctors, and emergency medicine physicians commonly use this code when evaluating patients with bleeding problems or managing conditions like liver disease or malnutrition that affect clotting ability. It frequently appears on EOB statements for patients undergoing coagulation studies or receiving blood products.",
