    "code": "D68.51",
    "rawCode": "D6851",
    "shortDesc": "Activated protein C resistance",
    "longDesc": "Activated protein C resistance",
    "plainEnglish": "Activated protein C resistance is a blood clotting disorder where your body doesn't respond normally to a natural protein (activated protein C) that usually helps prevent dangerous blood clots. This condition increases your risk of developing blood clots in your veins, which can be serious if they travel to your lungs or brain. Most commonly, this is caused by a genetic factor called Factor V Leiden mutation, which you inherit from your parents.",
    "whoUses": "Hematologists, thrombosis specialists, and primary care physicians use this code when evaluating patients with unexplained blood clots, recurrent miscarriages, or a family history of clotting disorders. It commonly appears on EOB statements when patients undergo hypercoagulability testing or genetic screening after a clotting event.",
