    "rawCode": "D6852",
    "shortDesc": "Prothrombin gene mutation",
    "longDesc": "Prothrombin gene mutation",
    "plainEnglish": "You have a genetic variation in the gene that controls prothrombin, a protein your body uses to form blood clots. This inherited change increases your risk of developing dangerous blood clots in your veins (deep vein thrombosis) or lungs (pulmonary embolism), especially when combined with other risk factors like surgery, pregnancy, or prolonged immobility. Many people with this mutation never develop clots, but knowing you have it helps doctors decide whether you need blood-thinning medication to prevent problems.",
    "whoUses": "Hematologists, primary care physicians, and thrombosis specialists use this code when diagnosing inherited clotting disorders or managing patients with a personal or family history of blood clots. It may appear on EOB statements for patients undergoing genetic testing, thrombophilia workup, or being evaluated for recurrent clotting events, though the condition itself is often discovered incidentally during clotting disorder screening.",
