    "plainEnglish": "This code describes an inherited blood clotting disorder that increases your risk of forming dangerous blood clots—but it's a type that doesn't fit into the more common categories like Factor V Leiden or prothrombin gene mutations. People with this condition have an abnormality in their blood that makes clots form more easily than normal, which can lead to deep vein thrombosis, pulmonary embolism, or stroke.",
    "whoUses": "Hematologists, cardiologists, and vascular surgeons use this code when diagnosing and managing patients with genetic clotting disorders that require anticoagulation therapy or monitoring. While it may appear on an EOB if you had specialized genetic testing or received treatment for a clotting complication, it's less common on routine patient statements than more frequently diagnosed thrombophilias.",
