    "shortDesc": "Lupus anticoagulant syndrome",
    "longDesc": "Lupus anticoagulant syndrome",
    "plainEnglish": "Lupus anticoagulant syndrome is a blood clotting disorder where your immune system produces antibodies that interfere with your body's natural anticoagulants (blood-thinning proteins). Despite its name, this condition is not related to lupus (an autoimmune disease) and actually causes your blood to clot too easily rather than thin. Patients with this syndrome have an increased risk of blood clots in veins or arteries, which can lead to stroke, heart attack, or miscarriage in pregnancy.",
    "whoUses": "Hematologists, rheumatologists, and internal medicine doctors diagnose and manage lupus anticoagulant syndrome, often identified through blood tests (prolonged PTT or aPTT). This code frequently appears on EOB statements, particularly for patients requiring anticoagulation therapy or being evaluated for unexplained blood clots.",
