    "plainEnglish": "This code describes an increased tendency for your blood to form clots (thrombophilia), but one that doesn't fit into the more common categories like Factor V Leiden or prothrombin gene mutations. You may have an inherited condition affecting how your blood clots, an acquired clotting disorder, or a combination of factors that make blood clots more likely to form—raising your risk for deep vein thrombosis, pulmonary embolism, or stroke.",
    "whoUses": "Hematologists, internal medicine physicians, and cardiologists use this code when evaluating patients with recurrent blood clots or unusual clotting patterns. It commonly appears on EOB statements for patients undergoing clotting studies, anticoagulation therapy, or investigation of clot-related events.",
