    "whoUses": "Hematologists (blood specialists) and coagulation specialists most commonly use this code when diagnosing and managing patients with uncommon clotting defects after standard coagulation testing. It may appear on an EOB if you've had specialized blood work or treatment for a bleeding disorder that required referral to a hematology clinic, though it's not as common as other bleeding disorder codes.",
