    "plainEnglish": "This code indicates that your blood isn't clotting normally, but the exact cause hasn't been identified or specified by your doctor. Blood clotting is essential to stop bleeding when you're injured, so a defect in this process means you might bleed more easily, have difficulty stopping bleeding, or experience excessive bruising. Your doctor may need to perform additional tests to determine what's specifically wrong with your clotting system.",
