    "shortDesc": "Allergic purpura",
    "longDesc": "Allergic purpura",
    "plainEnglish": "Allergic purpura is a condition where your immune system reacts to a trigger (like an infection, medication, or food) by attacking small blood vessels in your skin, causing red or purple bruises and spots that don't blanch when you press on them. You might also experience joint pain, abdominal discomfort, or kidney problems depending on the severity. This is different from other types of bleeding disorders because it's caused by an allergic or inflammatory reaction rather than a problem with your blood's ability to clot.",
