    "plainEnglish": "This diagnosis means your blood platelets (the cells that help form clots and stop bleeding) are not functioning properly, even though you may have a normal number of them. These defective platelets don't work as effectively as they should, so your blood may not clot as well as it needs to, putting you at risk for unusual bruising, bleeding gums, or prolonged bleeding from cuts. This can be an inherited condition or develop due to medications, bone marrow disorders, or other medical issues.",
