    "longDesc": "Immune thrombocytopenic purpura",
    "plainEnglish": "Immune thrombocytopenic purpura (ITP) is a bleeding disorder where your immune system mistakenly attacks and destroys platelets—the blood cells responsible for clotting. This causes your platelet count to drop dangerously low, leading to easy bruising, spontaneous bleeding (nosebleeds, bleeding gums), and small red or purple spots on your skin. The condition can range from mild to severe, and treatment depends on how low your platelet count drops and whether you're having active bleeding.",
