    "plainEnglish": "This is a bleeding disorder you were born with or inherited from a parent, where your body doesn't make enough platelets (the cells that help blood clot). Because you have fewer platelets than normal, you may bruise easily, have small red or purple spots on your skin (called petechiae), or bleed more than usual from minor cuts or nosebleeds. The condition is genetic, meaning it runs in families or appeared as a new change in your genes.",
