    "longDesc": "Thrombocytopenia, unspecified",
    "plainEnglish": "Thrombocytopenia means you have a lower-than-normal number of platelets in your blood—the tiny cells that help your blood clot and stop bleeding. This diagnosis code is used when a doctor has identified that your platelet count is low, but either the specific cause hasn't been determined yet or it doesn't fit into a more specific category. You might experience unusual bruising, prolonged bleeding from minor cuts, or notice tiny red or purple spots on your skin.",
    "whoUses": "Hematologists (blood specialists), primary care doctors, and emergency medicine physicians commonly use this code when evaluating patients with low platelet counts. It frequently appears on EOB statements for lab work, hospital visits, or specialist consultations related to bleeding concerns, though the code may be replaced with a more specific diagnosis once the underlying cause is identified.",
    "billable": true,
