    "code": "D70.0",
    "rawCode": "D700",
    "shortDesc": "Congenital agranulocytosis",
    "longDesc": "Congenital agranulocytosis",
    "plainEnglish": "Congenital agranulocytosis is a rare blood disorder that a person is born with, in which their bone marrow doesn't produce enough neutrophils (a crucial type of white blood cell that fights infections). Without adequate neutrophils, the immune system becomes severely weakened, making the person extremely susceptible to serious bacterial and fungal infections even from minor exposures. People with this condition typically experience frequent, severe infections starting in infancy or early childhood and require close medical monitoring and sometimes preventive antibiotics.",
    "whoUses": "Hematologists, pediatricians, and immunologists primarily use this code when diagnosing and managing infants or children with this inherited condition. It appears on EOB statements when a patient receives care for diagnosis, monitoring, or treatment of this congenital blood disorder, though the condition itself is relatively rare in clinical practice.",
