    "shortDesc": "Agranulocytosis secondary to cancer chemotherapy",
    "longDesc": "Agranulocytosis secondary to cancer chemotherapy",
    "plainEnglish": "Agranulocytosis secondary to cancer chemotherapy means that chemotherapy drugs used to treat cancer have damaged your bone marrow's ability to produce white blood cells called neutrophils, leaving you with very few of these infection-fighting cells in your blood. This condition puts you at high risk for serious infections because your immune system is severely weakened. You might experience fever, chills, mouth sores, or other signs of infection during or after chemotherapy treatment.",
    "whoUses": "Oncologists and hematologists use this code when documenting chemotherapy side effects during cancer treatment. It commonly appears on EOB statements for cancer patients undergoing active chemotherapy, as it represents a serious but expected adverse effect that may require hospitalization, additional medications, or treatment modifications.",
