    "rawCode": "D702",
    "shortDesc": "Other drug-induced agranulocytosis",
    "longDesc": "Other drug-induced agranulocytosis",
    "plainEnglish": "Agranulocytosis is a serious condition where your body stops producing enough white blood cells called neutrophils, which normally fight infections and protect you from bacteria. In this case, a medication you're taking is causing your bone marrow to fail to make these infection-fighting cells, leaving you vulnerable to severe infections. You might experience fever, sore throat, mouth sores, or signs of infection because your immune system can't defend itself properly.",
    "whoUses": "Hematologists, oncologists, and internists use this code when a patient develops dangerously low white blood cell counts as a known side effect of drugs like chemotherapy agents, certain antibiotics, antithyroid medications, or immunosuppressants. This code frequently appears on EOB statements when patients require hospitalization or emergency care for infection monitoring related to medication-induced bone marrow suppression.",
