    "rawCode": "D703",
    "shortDesc": "Neutropenia due to infection",
    "longDesc": "Neutropenia due to infection",
    "plainEnglish": "Neutropenia due to infection means you have an abnormally low number of neutrophils (a type of white blood cell that fights bacterial infections) because your body is fighting off an active infection. When your body mounts a strong immune response to combat a serious infection, it can use up neutrophils faster than your bone marrow can produce them, temporarily reducing your white blood cell count and making you more vulnerable to additional infections.",
    "whoUses": "Infectious disease specialists, internal medicine doctors, and hospitalists commonly use this code when treating patients with severe bacterial, fungal, or viral infections that have caused a secondary drop in white blood cells. This code typically appears on hospital bills and EOB statements for patients admitted with serious infections like sepsis, pneumonia, or other systemic infections, rather than on routine outpatient claims.",
