    "shortDesc": "Cyclic neutropenia",
    "longDesc": "Cyclic neutropenia",
    "plainEnglish": "Cyclic neutropenia is a rare blood disorder where your body doesn't produce enough of a specific type of white blood cell (called neutrophils) that fights infections, and this shortage happens in a repeating cycle rather than all the time. People with this condition experience periodic episodes of low neutrophil counts lasting several days, followed by normal counts, in a predictable pattern (usually every 3 weeks), which makes them prone to recurring mouth sores, infections, and fever during the low phases.",
    "whoUses": "Hematologists, infectious disease specialists, and primary care physicians use this code when diagnosing and monitoring cyclic neutropenia, particularly in patients presenting with recurrent infections in a cyclic pattern. It appears on EOB statements when patients require specialized blood work monitoring, antibiotics during flare-ups, or treatment with medications like G-CSF (filgrastim) that stimulate neutrophil production.",
