    "shortDesc": "Leukocyte adhesion deficiency",
    "longDesc": "Leukocyte adhesion deficiency",
    "plainEnglish": "Leukocyte adhesion deficiency is a rare genetic disorder where white blood cells cannot attach properly to blood vessel walls and tissues. This makes it extremely difficult for your immune system to reach and fight infections, leaving you vulnerable to frequent, severe, and sometimes life-threatening bacterial and fungal infections. People with this condition often experience recurring infections in the skin, lungs, mouth, and other areas, even with treatment.",
    "whoUses": "Immunologists, hematologists, and pediatricians primarily diagnose and manage this condition, typically identified in infants or young children with recurrent infections. This code rarely appears on patient EOB statements as it is a rare genetic disorder usually managed through specialized immunology clinics and research centers rather than routine medical billing.",
