    "shortDesc": "Other functional disorders of polymorphonuclear neutrophils",
    "longDesc": "Other functional disorders of polymorphonuclear neutrophils",
    "plainEnglish": "This code describes a disorder where your white blood cells called neutrophils (a type of immune cell) don't work properly, but the problem isn't one of the more common neutrophil diseases. Your body may produce normal-looking neutrophils, but they have difficulty fighting off infections, moving to infected areas, or destroying bacteria and fungi—essentially your immune system's front-line soldiers aren't performing their job correctly. This can leave you more vulnerable to infections or make it harder for your body to clear them.",
    "whoUses": "Immunologists, hematologists, and infectious disease specialists use this code when diagnosing immune system disorders. It appears in hospital records and specialist consultations rather than routinely on patient EOBs, as it's typically documented during workup for recurrent infections or immune deficiency evaluation.",
