    "shortDesc": "Functional disorders of polymorphonuclear neutrophils, unsp",
    "longDesc": "Functional disorders of polymorphonuclear neutrophils, unspecified",
    "plainEnglish": "This code describes a problem with your white blood cells called neutrophils, which normally help fight infections and clear debris from your body. When you have a functional disorder of these cells, it means they're not working properly even though they may appear normal under a microscope—they might not move correctly, kill bacteria effectively, or respond to infection signals the way they should. This can make you more prone to infections or have difficulty healing from wounds.",
    "whoUses": "Immunologists, hematologists, and infectious disease specialists use this code when evaluating patients with recurrent or unusual infections and abnormal neutrophil function testing. It typically appears on EOB statements when patients undergo specialized immune function testing or are being treated for infection-related complications due to white blood cell dysfunction.",
