    "code": "D72.110",
    "rawCode": "D72110",
    "shortDesc": "Idiopathic hypereosinophilic syndrome [IHES]",
    "longDesc": "Idiopathic hypereosinophilic syndrome [IHES]",
    "plainEnglish": "Idiopathic hypereosinophilic syndrome (IHES) is a rare blood disorder where your body produces too many eosinophils—a type of white blood cell—for no identifiable reason. This abnormal buildup of eosinophils can damage various organs, particularly the heart, lungs, and nervous system, causing symptoms like fatigue, fever, rash, or shortness of breath. 'Idiopathic' simply means doctors cannot determine the underlying cause, distinguishing this condition from eosinophilia caused by allergies, parasites, or other known triggers.",
    "whoUses": "Hematologists and internal medicine specialists typically diagnose and manage IHES, often with input from cardiologists or pulmonologists if organ involvement is present. This code frequently appears on EOB statements for patients undergoing diagnostic testing (blood work, bone marrow biopsies) and ongoing treatment monitoring, though it remains a relatively uncommon diagnosis.",
