    "longDesc": "Lymphocytic Variant Hypereosinophilic Syndrome [LHES]",
    "plainEnglish": "Lymphocytic Variant Hypereosinophilic Syndrome (LHES) is a rare blood disorder where your body produces too many eosinophils—a type of white blood cell—and these abnormal cells damage various organs over time. This condition is driven by T-lymphocytes (another type of white blood cell) that are behaving abnormally, causing chronic inflammation. Patients may experience fatigue, skin rashes, cough, heart problems, or organ dysfunction depending on which tissues are affected.",
    "whoUses": "Hematologists, oncologists, and immunologists typically diagnose and manage LHES, often in specialized centers or academic medical centers due to its rarity. This code appears on EOBs for patients undergoing bone marrow biopsies, flow cytometry testing, or specialist consultations related to persistent eosinophilia.",
