    "whoUses": "Dermatologists, allergists, and internal medicine physicians diagnose and treat DRESS syndrome, often in collaboration with infectious disease specialists since it can mimic infections. This code appears on EOBs when a patient is evaluated or hospitalized for suspected drug-induced systemic allergic reactions, typically resulting in significant medical expenses due to diagnostic testing and hospitalization.",
