    "longDesc": "Plasmacytosis",
    "plainEnglish": "Plasmacytosis means your blood has an abnormally high number of plasma cells, which are white blood cells that produce antibodies to fight infections and disease. This can occur as a response to infection, inflammation, or certain blood disorders, and your doctor may order blood tests to determine the underlying cause. You might not have any symptoms, or you could experience fatigue, fever, or other signs depending on what condition is causing the elevated plasma cells.",
    "whoUses": "Hematologists, oncologists, and internal medicine physicians use this code when reviewing lab results showing elevated plasma cells on a blood smear or complete blood count. This code rarely appears on patient EOB statements since it describes a laboratory finding rather than a billable diagnosis on its own; it typically appears in medical records as part of workup for underlying conditions.",
    "billable": true,
