    "shortDesc": "Basophilia",
    "longDesc": "Basophilia",
    "plainEnglish": "Basophilia means you have an abnormally high number of basophils, which are a type of white blood cell that helps your body fight infection and manage allergic reactions. This condition is usually detected through a blood test and can be associated with certain infections, allergies, leukemia, or other blood disorders. You might not notice any symptoms, but your doctor will want to investigate what's causing the elevated basophil count.",
    "whoUses": "Hematologists, oncologists, and internal medicine physicians commonly use this code when reviewing complete blood count (CBC) results and investigating abnormal white blood cell patterns. It frequently appears on patient EOBs when laboratory work has identified an elevated basophil percentage or absolute count requiring further evaluation.",
