    "longDesc": "Bandemia",
    "plainEnglish": "Bandemia means you have an unusually high number of immature white blood cells (called band cells or stab cells) circulating in your bloodstream. This typically happens when your body is fighting a serious infection or dealing with significant stress, causing your bone marrow to release these young infection-fighting cells before they're fully mature. It's usually a sign that your immune system is working overtime to combat something serious.",
    "whoUses": "This code is used by hematologists, infectious disease specialists, and emergency medicine physicians when reviewing blood test results (a complete blood count or CBC with differential) in hospitalized or critically ill patients with infections, sepsis, or other acute illnesses. It appears less commonly on patient EOB statements since it's typically documented in hospital inpatient settings rather than outpatient billing.",
