    "code": "D73.1",
    "rawCode": "D731",
    "shortDesc": "Hypersplenism",
    "longDesc": "Hypersplenism",
    "plainEnglish": "Hypersplenism means your spleen is working too hard and becoming overactive, causing it to remove too many blood cells from your circulation. This can lead to low counts of red blood cells (causing anemia), white blood cells (increasing infection risk), or platelets (causing bleeding problems), and your spleen may become enlarged. The condition is usually secondary to another disease like cirrhosis, leukemia, or an autoimmune disorder rather than a primary problem with the spleen itself.",
    "whoUses": "Hematologists, internists, and gastroenterologists commonly use this code when evaluating patients with low blood cell counts and an enlarged spleen. It appears on EOBs when patients undergo blood work, imaging studies, or specialist consultations to diagnose the cause of cytopenias (low blood cell counts).",
