    "rawCode": "D732",
    "shortDesc": "Chronic congestive splenomegaly",
    "longDesc": "Chronic congestive splenomegaly",
    "plainEnglish": "Chronic congestive splenomegaly means your spleen has become permanently enlarged due to a backup of blood or fluid within it, usually from problems with blood circulation through the liver or heart. This happens over time (not suddenly), and the enlarged spleen may cause abdominal discomfort, a feeling of fullness, or problems with blood cell counts because the spleen isn't filtering blood normally. Common causes include cirrhosis, heart failure, or portal hypertension—conditions that slow down blood flow and cause it to pool in the spleen.",
    "whoUses": "Gastroenterologists, hepatologists, hematologists, and internal medicine physicians use this code when managing patients with liver disease, heart failure, or blood disorders that cause spleen enlargement. It commonly appears on EOB statements for patients undergoing evaluation or follow-up care for chronic liver or circulatory conditions.",
