    "shortDesc": "Cyst of spleen",
    "longDesc": "Cyst of spleen",
    "plainEnglish": "A cyst of the spleen is a fluid-filled sac that forms in or on your spleen, which is an organ in your upper left abdomen that helps filter blood and fight infections. Most splenic cysts are discovered by chance on imaging tests and don't cause symptoms, though some people may experience pain or fullness in the upper left side of their abdomen if the cyst is large. These cysts can be present from birth (congenital) or develop later in life, and they're usually monitored with periodic imaging rather than treated unless they cause problems.",
    "whoUses": "Gastroenterologists, radiologists, and general surgeons most commonly diagnose and manage splenic cysts using ultrasound or CT imaging. This code appears on patient EOB statements when imaging tests specifically identify a cyst and documentation warrants coding it as a separate diagnosis, though it may not appear if the cyst is incidental and asymptomatic.",
