    "shortDesc": "Infarction of spleen",
    "longDesc": "Infarction of spleen",
    "plainEnglish": "Infarction of the spleen means that part of your spleen has died because blood flow to that area was blocked or severely reduced. The spleen is an organ that helps filter blood and fight infections, so when a section dies from lack of blood supply, it can cause sudden pain in the upper left side of your abdomen, along with fever and nausea. This condition usually requires emergency medical attention and imaging studies like an ultrasound or CT scan to confirm the diagnosis.",
    "whoUses": "Emergency medicine physicians, general internists, and gastroenterologists most commonly diagnose and manage splenic infarction, typically in hospital settings after a patient presents with acute abdominal pain. This code appears on EOB statements when a patient has been hospitalized or seen in an emergency department for this acute vascular event, and may be associated with imaging studies, laboratory work, or potentially surgical consultation.",
