    "longDesc": "Neutropenic splenomegaly",
    "plainEnglish": "Neutropenic splenomegaly means you have an enlarged spleen (splenomegaly) along with a low count of neutrophils, which are white blood cells that fight infections. This can happen as a side effect of certain medications, chemotherapy, or as part of an underlying condition that affects how your bone marrow produces these infection-fighting cells. You might experience fatigue, frequent infections, or feel fullness or pain in your upper left abdomen where your enlarged spleen is located.",
    "whoUses": "Hematologists, oncologists, and internal medicine doctors use this code when treating patients with bone marrow disorders, chemotherapy side effects, or conditions affecting white blood cell production. It appears on EOB statements primarily for patients undergoing cancer treatment or being evaluated for blood disorders, though it's less commonly seen on routine patient EOBs compared to more straightforward diagnoses.",
