    "code": "D74.0",
    "rawCode": "D740",
    "shortDesc": "Congenital methemoglobinemia",
    "longDesc": "Congenital methemoglobinemia",
    "plainEnglish": "Congenital methemoglobinemia is a rare inherited condition where your body has trouble converting a damaged form of hemoglobin (the protein in red blood cells that carries oxygen) back to its normal, functional form. This happens because you were born with a deficiency in the enzyme that performs this conversion, leading to an abnormal buildup of methemoglobin. Patients with this condition may experience bluish-tinged skin (especially around the lips and fingernails), fatigue, and shortness of breath because the damaged hemoglobin cannot carry oxygen effectively.",
    "whoUses": "This code is used primarily by hematologists, pediatricians, and emergency medicine physicians when diagnosing and managing patients with this rare genetic disorder. It occasionally appears on EOB statements for patients undergoing genetic testing, follow-up appointments, or treatment related to their methemoglobinemia, though it is uncommon since the condition is rare.",
