    "rawCode": "D749",
    "shortDesc": "Methemoglobinemia, unspecified",
    "longDesc": "Methemoglobinemia, unspecified",
    "plainEnglish": "Methemoglobinemia is a rare blood condition where a form of hemoglobin (the protein that carries oxygen in your blood) becomes chemically altered and cannot deliver oxygen normally to your tissues. This can happen from exposure to certain medications, chemicals, or food additives, or sometimes from a genetic condition, leaving your body unable to convert the altered hemoglobin back to its normal form. Patients may experience bluish discoloration of the lips and skin, shortness of breath, fatigue, or a rapid heartbeat, depending on the severity.",
    "whoUses": "This code is used by emergency medicine physicians, hematologists, and toxicologists when evaluating patients with unexplained cyanosis (blue skin) or respiratory distress from chemical or medication exposure. It may appear on EOB statements for patients seen in emergency departments or specialty clinics investigating the cause of low blood oxygen levels.",
