    "longDesc": "Familial erythrocytosis",
    "plainEnglish": "Familial erythrocytosis is a rare inherited condition where your body naturally produces too many red blood cells compared to what most people make. This happens because of a genetic trait passed down through your family rather than from an illness or environmental factor. People with this condition may have higher than normal red blood cell counts, which can make their blood thicker and potentially increase risks like blood clots, but many people don't experience any symptoms at all.",
    "whoUses": "Hematologists (blood specialists) and genetic specialists diagnose and manage familial erythrocytosis, often in a family medicine or internal medicine context after abnormal blood work. This code is less common on patient EOB statements since it's a rare condition, but appears when patients undergo genetic testing or specialized hematology evaluation.",
