    "plainEnglish": "Secondary polycythemia means your body is producing too many red blood cells, but this isn't a primary blood disorder—it's happening as a result of another underlying condition or circumstance. This excess of red blood cells is your body's response to something else, such as chronic lung disease, heart disease, living at high altitude, or even certain cancers; it can make your blood thicker and increase your risk of clots.",
    "whoUses": "Hematologists, pulmonologists, cardiologists, and oncologists use this code when evaluating patients with elevated red blood cell counts caused by underlying medical conditions. It commonly appears on EOB statements when patients undergo blood work showing polycythemia and the physician documents that it's secondary to another diagnosed condition rather than a primary blood disorder.",
