    "shortDesc": "Myelofibrosis",
    "longDesc": "Myelofibrosis",
    "plainEnglish": "Myelofibrosis is a rare blood disorder where bone marrow becomes scarred and stiff, making it harder for your body to produce healthy blood cells. This scarring can lead to anemia (too few red blood cells), infections (too few white blood cells), and abnormal bleeding or bruising (too few platelets). Over time, the spleen and liver may enlarge as they try to compensate by making blood cells, which can cause abdominal discomfort and fatigue.",
    "whoUses": "Hematologists (blood specialists) and oncologists diagnose and manage myelofibrosis, often using bone marrow biopsies to confirm the diagnosis. This code commonly appears on patient EOBs for blood work, specialist consultations, and imaging studies, and may be tied to ongoing monitoring or treatment with medications like JAK inhibitors.",
