    "code": "D75.821",
    "rawCode": "D75821",
    "shortDesc": "Non-immune heparin-induced thrombocytopenia",
    "longDesc": "Non-immune heparin-induced thrombocytopenia",
    "plainEnglish": "Non-immune heparin-induced thrombocytopenia (HIT) is a rare blood clotting complication that occurs when you receive the blood thinner heparin, but your immune system hasn't developed antibodies against it. In this type of HIT, your platelet count drops because heparin directly damages or activates your platelets, rather than through an immune reaction. You might experience unusual bruising, bleeding, or blood clots forming in your veins or arteries while taking heparin.",
    "whoUses": "Hematologists, cardiologists, intensivists, and hospitalists use this code when managing patients on heparin therapy who develop a sudden drop in platelet count. This code may appear on EOB statements for hospitalized patients or those undergoing cardiac procedures, though it's relatively uncommon and typically documented during acute hospital stays rather than outpatient care.",
