    "rawCode": "D75822",
    "shortDesc": "Immune-mediated heparin-induced thrombocytopenia",
    "longDesc": "Immune-mediated heparin-induced thrombocytopenia",
    "plainEnglish": "This is a serious blood clotting disorder that develops when your immune system reacts to heparin, a common blood thinner used to prevent clots. Your body mistakenly attacks platelets (cells that help blood clot) in response to the heparin, causing the platelet count to drop dangerously low and paradoxically increasing your risk of abnormal blood clots. Symptoms may include unusual bruising, bleeding, or signs of blood clots like leg pain or shortness of breath.",
    "whoUses": "Hematologists and hospitalists use this code when diagnosing patients receiving heparin therapy who develop unexplained thrombocytopenia (low platelet counts). It commonly appears on EOB statements for patients hospitalized or treated in anticoagulation clinics, as recognition of this condition requires immediate medication changes and close monitoring.",
