    "plainEnglish": "This diagnosis describes a rare blood clotting disorder that develops in some patients after they receive heparin, a common blood thinner medication. In this condition, the body's platelet count drops significantly (thrombocytopenia) because the immune system reacts abnormally to heparin, causing blood clots to form in veins or arteries even as platelet numbers fall—a dangerous combination that requires immediate medical attention and switching to a different blood thinner.",
