    "shortDesc": "Heparin-induced thrombocytopenia, unspecified",
    "longDesc": "Heparin-induced thrombocytopenia, unspecified",
    "plainEnglish": "Heparin-induced thrombocytopenia (HIT) is a serious blood condition that develops when your body has an abnormal immune reaction to heparin, a common blood-thinning medication. This reaction causes your platelet count to drop significantly, which increases your risk of dangerous blood clots forming in your veins and arteries—the opposite of what the heparin was supposed to prevent. If you've received heparin during hospitalization or treatment and developed unexplained low platelets or blood clots, your doctor may have coded this diagnosis.",
