    "code": "D75.9",
    "rawCode": "D759",
    "shortDesc": "Disease of blood and blood-forming organs, unspecified",
    "longDesc": "Disease of blood and blood-forming organs, unspecified",
    "plainEnglish": "This code is used when a patient has a disease affecting their blood or the organs that make blood (like the bone marrow), but the doctors haven't identified the specific condition yet. Your blood is made in your bone marrow and travels through your body carrying oxygen and fighting infections, so problems in this system can affect your overall health. This is essentially a placeholder diagnosis that your doctor will use temporarily until more testing pinpoints exactly what's wrong.",
    "whoUses": "Hematologists (blood specialists), internists, and emergency medicine doctors use this code when initial blood work shows abnormalities but the specific diagnosis hasn't been determined. It's less common on patient EOBs since most insurers prefer specific diagnoses, but you may see it if your doctor is still investigating unexplained blood test results or bone marrow problems.",
