    "shortDesc": "Glucose-6-phosphate dehydrgnse (G6PD) defic without anemia",
    "longDesc": "Glucose-6-phosphate dehydrogenase (G6PD) deficiency without anemia",
    "plainEnglish": "You have a genetic condition where your red blood cells lack or don't produce enough of an enzyme called glucose-6-phosphate dehydrogenase (G6PD), which normally protects these cells from damage. Right now, you don't have anemia (low red blood cell count), but this deficiency means your red blood cells are more fragile and can break down if exposed to certain triggers like specific medications, infections, fava beans, or other oxidative stressors. It's important to know which foods and medicines to avoid to prevent a hemolytic crisis where your red blood cells break down rapidly.",
    "whoUses": "Hematologists and primary care physicians use this code when they've identified G6PD deficiency through genetic or enzyme testing, typically during routine screening or after a patient reports a family history. It's common in patients of African, Mediterranean, or Asian descent and may appear on EOB statements when genetic testing or specialized blood work is performed to diagnose this carrier condition.",
