    "rawCode": "D761",
    "shortDesc": "Hemophagocytic lymphohistiocytosis",
    "longDesc": "Hemophagocytic lymphohistiocytosis",
    "plainEnglish": "Hemophagocytic lymphohistiocytosis (HLH) is a rare and serious condition where certain immune cells become overactive and start attacking and consuming your blood cells and bone marrow cells, leading to dangerously low blood cell counts. This causes severe inflammation throughout your body and can result in symptoms like high fever, enlarged spleen and liver, bleeding problems, and organ damage. It can be triggered by infections, cancer, or genetic factors, and requires urgent treatment to control the immune system's dangerous overreaction.",
    "whoUses": "Hematologists, oncologists, immunologists, and pediatricians use this code when diagnosing and treating HLH, which is often identified in intensive care or hospital settings. This code appears less frequently on routine patient EOBs but commonly shows up on hospital bills and insurance claims for seriously ill patients undergoing advanced diagnostic testing and specialized treatment.",
