    "longDesc": "Hemophagocytic syndrome, infection-associated",
    "plainEnglish": "Hemophagocytic syndrome is a rare but serious condition where your immune system overreacts to an infection, causing it to attack and destroy your own blood cells and bone marrow. This typically happens in response to viral infections (like EBV or CMV), bacterial infections, or sometimes fungal infections, and leads to symptoms like high fever, enlarged spleen and liver, low blood cell counts, and bleeding problems.",
    "whoUses": "Hematologists, infectious disease specialists, and intensivists use this code when diagnosing and treating this life-threatening condition, typically in hospital or intensive care settings. It appears on EOB statements primarily for patients hospitalized with severe infections complicated by immune dysregulation, though it is relatively uncommon in routine outpatient care.",
