    "code": "D78.12",
    "rawCode": "D7812",
    "shortDesc": "Accidental pnctr & lac of the spleen during oth procedure",
    "longDesc": "Accidental puncture and laceration of the spleen during other procedure",
    "plainEnglish": "This code describes an unintended injury to the spleen that occurred as a complication during a surgical or medical procedure—something that wasn't meant to happen but was an accident during the operation. The spleen is a small organ near your left kidney that helps filter blood and fight infections, so an accidental cut or puncture to it during surgery can cause internal bleeding and may require additional treatment or even emergency surgery to control the bleeding.",
    "whoUses": "This code is used by surgeons, anesthesiologists, and operating room staff when documenting surgical complications. It commonly appears on EOB statements as a complication code that may affect billing, hospital quality metrics, and insurance review, since it indicates a patient safety event that occurred during a planned procedure.",
