    "rawCode": "D7822",
    "shortDesc": "Postproc hemorrhage of the spleen following other procedure",
    "longDesc": "Postprocedural hemorrhage of the spleen following other procedure",
    "plainEnglish": "This code describes bleeding from the spleen that occurs after a surgical procedure or medical intervention that was not spleen-related surgery. The spleen is an organ that helps filter blood and fight infections, and sometimes bleeding can happen as a complication after procedures like abdominal surgery, biopsies, or other medical interventions. Depending on how much bleeding occurs, a patient might experience weakness, dizziness, or require additional treatment to stop the bleeding.",
    "whoUses": "This code is used by general surgeons, trauma surgeons, and interventional radiologists when managing postoperative complications in hospital settings. It commonly appears on EOB statements when a patient has required emergency treatment or readmission for bleeding complications after a procedure, and insurance needs to document that the bleeding was procedure-related rather than a pre-existing condition.",
