    "code": "D78.31",
    "rawCode": "D7831",
    "shortDesc": "Postprocedural hematoma of the spleen fol proc on spleen",
    "longDesc": "Postprocedural hematoma of the spleen following a procedure on the spleen",
    "plainEnglish": "This code describes abnormal bleeding that occurs in the spleen as a complication after a surgical procedure was performed on the spleen itself. A hematoma is a collection of blood that pools in one area, and in this case it developed as a result of the surgical procedure rather than from an injury or disease. Patients might experience pain in the upper left abdomen (where the spleen is located), bruising, or signs of anemia if the bleeding is significant.",
    "whoUses": "Surgeons, interventional radiologists, and hospital surgical teams use this code when documenting complications that occur during or after spleen surgery (such as splenectomy or splenic artery embolization). This code typically appears on patient EOBs when a patient has experienced a bleeding complication requiring additional treatment or monitoring following a planned spleen procedure.",
