    "shortDesc": "Postproc seroma of the spleen following other procedure",
    "longDesc": "Postprocedural seroma of the spleen following other procedure",
    "plainEnglish": "A seroma is a collection of clear fluid that builds up under the skin or in body tissues after surgery or a medical procedure. In this case, it occurred around the spleen (an organ that helps filter blood and fight infection) following a procedure other than spleen removal surgery. You might notice swelling, firmness, or mild discomfort in the area where the procedure was done, and your doctor may need to monitor it or drain it if it becomes problematic.",
