    "plainEnglish": "This code describes unexpected problems that occurred to your spleen during a surgical procedure, beyond the routine risks of surgery itself. These complications might include bleeding, infection, or accidental injury to the spleen that happened while your surgeon was operating on you or nearby structures. Depending on the specific complication, your surgeon may have needed to take additional steps during or after surgery to address the problem.",
    "whoUses": "General surgeons, trauma surgeons, and vascular surgeons use this code when documenting complications that arise during spleen surgery or procedures near the spleen. This code typically appears on EOB statements when a patient experiences an unexpected surgical complication that requires additional documentation for billing and medical record purposes.",
