    "shortDesc": "Immunodeficiency with increased immunoglobulin M [IgM]",
    "longDesc": "Immunodeficiency with increased immunoglobulin M [IgM]",
    "plainEnglish": "This condition means your immune system is not working properly, but specifically your body is making too much of one type of antibody called IgM while lacking other important immune defenses. People with this rare disorder often get frequent infections because even though they're producing extra IgM, they don't have enough of other antibodies (like IgG) that are needed to fight off germs effectively. You might experience recurrent bacterial, viral, or fungal infections, along with enlarged lymph nodes and spleen.",
    "whoUses": "This code is used by immunologists, infectious disease specialists, and primary care physicians when diagnosing immunodeficiency disorders. It rarely appears on patient EOB statements as a primary diagnosis but may be noted during specialized immune evaluation or in pediatric cases where the condition is first identified.",
    "billable": true,
    "isNew": false,
    "isRevised": false,
