    "rawCode": "D809",
    "shortDesc": "Immunodeficiency with predominantly antibody defects, unsp",
    "longDesc": "Immunodeficiency with predominantly antibody defects, unspecified",
    "plainEnglish": "Your immune system isn't making enough antibodies, which are proteins your body uses to fight off infections. Antibodies normally help your white blood cells identify and destroy bacteria, viruses, and other harmful invaders. Without adequate antibodies, you may get frequent or more serious infections, and your body struggles to fight them off.",
    "whoUses": "Immunologists and infectious disease specialists use this code when diagnosing primary immunodeficiency disorders characterized by insufficient antibody production. It commonly appears on EOBs for patients undergoing immunological testing or receiving immunoglobulin replacement therapy.",
