    "code": "D81.0",
    "rawCode": "D810",
    "shortDesc": "Severe combined immunodeficiency with reticular dysgenesis",
    "longDesc": "Severe combined immunodeficiency [SCID] with reticular dysgenesis",
    "plainEnglish": "Severe combined immunodeficiency with reticular dysgenesis is a rare, inherited condition where a baby is born with an extremely underdeveloped immune system that cannot fight infections effectively. The bone marrow fails to develop properly, preventing the formation of the immune cells (T cells, B cells, and sometimes neutrophils) needed to protect against bacteria, viruses, and other harmful invaders. Affected infants typically develop serious, life-threatening infections early in life and require immediate specialized medical intervention.",
    "whoUses": "Pediatric immunologists, hematologists, and neonatologists diagnose and treat this condition, typically within the first weeks of life when severe infections appear. This code rarely appears on routine patient EOBs but rather on statements related to hospitalization, bone marrow transplantation, or gene therapy for affected infants.",
