    "shortDesc": "Adenosine deaminase 2 deficiency",
    "longDesc": "Adenosine deaminase 2 deficiency",
    "plainEnglish": "Adenosine deaminase 2 (ADA2) deficiency is a rare genetic immune disorder where your body doesn't produce enough of an enzyme called adenosine deaminase 2, which is important for immune system function and blood vessel health. People with this condition typically experience recurrent infections, inflammation in blood vessels (which can affect the brain, heart, and other organs), and sometimes a stroke-like condition called vasculitis. This is an inherited condition that requires specialized medical care and monitoring.",
    "whoUses": "Immunologists, pediatricians, and geneticists primarily use this code, as ADA2 deficiency is usually diagnosed in childhood and requires specialist care. This code appears less commonly on patient EOBs due to the rarity of the condition, but it is used when documenting care for patients with confirmed ADA2 deficiency to track treatment and follow-up visits.",
