    "plainEnglish": "Adenosine deaminase (ADA) deficiency is a rare inherited immune system disorder where the body lacks enough of an enzyme needed to break down certain substances in immune cells, causing those cells to accumulate toxic materials and gradually stop working. This leads to a severely weakened immune system that cannot fight off infections effectively, leaving patients vulnerable to frequent and serious bacterial, viral, and fungal infections. The severity can vary widely—some patients have profound immunodeficiency from infancy, while others may develop symptoms more gradually.",
    "whoUses": "Immunologists and pediatricians primarily diagnose and manage ADA deficiency, often in consultation with geneticists and hematologists. This code appears in specialized medical records and insurance claims for affected patients but is rarely seen on typical patient EOB statements due to the condition's extreme rarity; patients with confirmed ADA deficiency typically receive care through referral centers specializing in primary immunodeficiencies.",
