    "longDesc": "Purine nucleoside phosphorylase [PNP] deficiency",
    "plainEnglish": "PNP deficiency is a rare genetic disorder where your body lacks an enzyme needed to break down certain compounds from your diet and cells. Without this enzyme, toxic substances build up in your body—especially in immune cells—which severely weakens your immune system and makes you vulnerable to serious infections. This condition is typically diagnosed in infancy or early childhood when a baby experiences recurrent, severe infections that are hard to treat.",
    "whoUses": "Immunologists, pediatricians, and geneticists use this code when managing patients with this rare inherited immune deficiency. It rarely appears on patient EOB statements as this is a specialized diagnosis primarily used in academic medical centers and specialized immunology clinics for genetic counseling and research purposes.",
