    "code": "D81.7",
    "rawCode": "D817",
    "shortDesc": "Major histocompatibility complex class II deficiency",
    "longDesc": "Major histocompatibility complex class II deficiency",
    "plainEnglish": "Major histocompatibility complex class II deficiency is a rare inherited immune disorder where your body lacks certain proteins (called MHC class II molecules) that are essential for your immune system to recognize and fight infections. Without these proteins, your immune system cannot properly signal white blood cells to attack germs and pathogens, leaving you severely vulnerable to bacterial, viral, and fungal infections starting in infancy. Patients typically experience recurrent, severe infections and may require specialized immune support or bone marrow transplantation to survive.",
    "whoUses": "Immunologists, pediatricians, and hematologists use this code to diagnose and manage patients with this severe combined immunodeficiency disorder. It is rarely seen on patient EOB statements because the condition is extremely uncommon (fewer than 100 cases worldwide) and is typically managed in specialized immunology centers or pediatric hospitals rather than in routine outpatient care.",
    "billable": true,
    "isNew": false,
    "isRevised": false,
