    "code": "D81.810",
    "rawCode": "D81810",
    "shortDesc": "Biotinidase deficiency",
    "longDesc": "Biotinidase deficiency",
    "plainEnglish": "Biotinidase deficiency is a rare inherited metabolic disorder where your body cannot properly process and recycle biotin (vitamin B7), an essential nutrient needed for hair, skin, and nerve health. Without enough active biotin, patients can develop hearing loss, skin rashes, hair loss, developmental delays, and neurological problems if left untreated. The good news is that this condition is highly manageable with biotin supplementation, which is why early detection through newborn screening is so important.",
    "whoUses": "Pediatricians, metabolic disorder specialists (genetic counselors and metabolic medicine doctors), and newborn screening programs commonly use this code. It frequently appears on EOBs for infants identified through newborn screening panels and for ongoing management visits in childhood, though it is a relatively uncommon diagnosis in the general population.",
