    "code": "D81.818",
    "rawCode": "D81818",
    "shortDesc": "Other biotin-dependent carboxylase deficiency",
    "longDesc": "Other biotin-dependent carboxylase deficiency",
    "plainEnglish": "This code describes a rare genetic metabolic disorder where your body cannot properly process biotin (a B vitamin) to make essential enzymes called carboxylases. These enzymes are needed to break down certain nutrients and produce energy, so when they don't work correctly, your body struggles to metabolize fats, amino acids, and other compounds properly. Patients with this condition may experience developmental delays, muscle weakness, skin problems, hair loss, or seizures, depending on which carboxylase enzymes are affected.",
    "whoUses": "Metabolic disease specialists, genetic counselors, and pediatricians typically diagnose and manage this condition, as it's an inherited genetic disorder usually identified in infancy or early childhood. This code appears less frequently on patient EOBs since it's a rare disorder, but when it does appear, it's usually in the context of specialized genetic testing, metabolic workup, or follow-up care at a metabolic disease center.",
