    "longDesc": "Biotin-dependent carboxylase deficiency, unspecified",
    "plainEnglish": "Biotin-dependent carboxylase deficiency is a rare inherited metabolic disorder where your body cannot properly use biotin (a B vitamin) to break down certain nutrients. This happens because your body lacks or has defective enzymes that need biotin to function, leading to a buildup of harmful substances and potentially causing developmental delays, seizures, breathing problems, or skin issues. The \"unspecified\" part means your doctor hasn't identified which specific enzyme is affected.",
    "whoUses": "Genetic specialists, metabolic disease experts, and pediatricians use this code when diagnosing or managing rare inherited disorders in infants and children. This code rarely appears on patient EOBs because it's extremely uncommon, but when it does, it's typically in the context of genetic testing, specialized metabolic workup, or treatment in academic medical centers.",
