    "code": "D81.82",
    "rawCode": "D8182",
    "shortDesc": "Activated Phosphoinositide 3-kinase Delta Syndrome [APDS]",
    "longDesc": "Activated Phosphoinositide 3-kinase Delta Syndrome [APDS]",
    "plainEnglish": "Activated Phosphoinositide 3-kinase Delta Syndrome (APDS) is a rare genetic immune disorder where a mutation causes a protein in your immune system to become overactive, leading to abnormal immune function. This condition typically results in recurrent infections, enlarged lymph nodes and spleen, autoimmune problems, and sometimes increased risk of certain cancers. People with APDS have difficulty fighting off infections and may experience chronic symptoms because their immune system isn't working properly.",
    "whoUses": "Immunologists and geneticists primarily diagnose and manage APDS, often after extensive immune system testing and genetic sequencing in pediatric patients presenting with early-onset recurrent infections. This code is relatively uncommon on patient EOBs as it's a rare disorder, but when present, it typically appears in records for specialized immunology consultations, genetic testing, or management of complications.",
