    "shortDesc": "Combined immunodeficiency, unspecified",
    "longDesc": "Combined immunodeficiency, unspecified",
    "plainEnglish": "Combined immunodeficiency means your body has significant weaknesses in multiple parts of its immune system, making it much harder to fight off infections. This can be caused by genetic disorders, bone marrow problems, or certain medical treatments, and people with this condition may get frequent, severe, or unusual infections that a healthy immune system would typically handle easily. When doctors use the 'unspecified' version of this code, it means they've determined you have a combined immune deficiency but haven't yet identified the exact underlying cause or type.",
    "whoUses": "Immunologists, hematologists, and infectious disease specialists typically use this code when evaluating patients with recurrent or opportunistic infections and abnormal immune cell counts. This code is less common on routine patient EOBs since it usually appears in specialty care settings, hospital admissions, or during comprehensive workups for immune disorders.",
