    "plainEnglish": "Wiskott-Aldrich syndrome is a rare inherited immune disorder that affects males, causing the body to have too few platelets (cells that help blood clot), increased susceptibility to infections, and often eczema (itchy skin rashes). People with this condition bleed more easily than normal and are at higher risk for infections and certain cancers because their immune system doesn't work properly. This is a serious condition that typically appears in early childhood and requires specialized medical management.",
    "whoUses": "Pediatric immunologists, hematologists, and geneticists primarily diagnose and manage Wiskott-Aldrich syndrome, often in children's hospitals with specialized immune disorder clinics. This code appears on EOB statements for affected children undergoing genetic testing, immune evaluations, and ongoing treatment for bleeding, infections, or complications of the syndrome.",
