    "shortDesc": "Di George's syndrome",
    "longDesc": "Di George's syndrome",
    "plainEnglish": "DiGeorge syndrome is a rare genetic condition where a person is born with developmental problems affecting the thymus gland (which helps fight infections), parathyroid glands (which control calcium levels), heart, and facial features. People with this condition may have a weakened immune system, low calcium levels that can cause seizures, heart defects, and distinctive facial characteristics. It occurs when a small piece of chromosome 22 is missing, and while some cases are mild, others can significantly affect how the immune system develops and functions.",
    "whoUses": "Pediatricians, immunologists, cardiologists, and geneticists typically diagnose and manage DiGeorge syndrome. This code commonly appears on EOB statements for children undergoing immune workup, cardiac evaluation, or genetic testing, and may be referenced for ongoing immunodeficiency management.",
