    "plainEnglish": "This diagnosis describes a rare genetic condition where a person has both a weakened immune system and unusually short arms and legs. People with this condition get infections more frequently because their body can't fight off germs as effectively as it should, and they also have skeletal abnormalities that result in short stature. It's an inherited disorder that requires ongoing medical management to prevent and treat infections.",
