    "plainEnglish": "Hyperimmunoglobulin E syndrome is a rare immune system disorder where your body produces abnormally high levels of a specific type of antibody called IgE. This overproduction causes your immune system to overreact to infections and allergens, leading to recurrent or severe bacterial skin infections, pneumonias, and allergic reactions. People with this condition often experience stubborn skin infections, unusual fungal infections, joint problems, and abnormal scarring.",
    "whoUses": "Immunologists, allergists, and infectious disease specialists use this code when evaluating patients with recurrent infections and abnormal immune responses. It occasionally appears on patient EOBs when patients are being evaluated for chronic or recurrent infections that don't respond to standard treatment, though diagnosis typically requires specialized testing.",
