    "code": "D83.2",
    "rawCode": "D832",
    "shortDesc": "Common variable immunodef w autoantibodies to B- or T-cells",
    "longDesc": "Common variable immunodeficiency with autoantibodies to B- or T-cells",
    "plainEnglish": "Common variable immunodeficiency with autoantibodies to B- or T-cells is a rare immune system disorder where your body doesn't make enough antibodies to fight infections, and at the same time produces antibodies that attack your own immune cells (B-cells or T-cells). This means you get frequent, serious infections because your immune system is weakened, while also damaging itself. Patients typically experience recurrent bacterial infections, chronic diarrhea, and other complications from having too few functional immune cells.",
    "whoUses": "Immunologists, infectious disease specialists, and hematologists diagnose and manage this condition. This code appears on EOB statements when a patient with this immunodeficiency disorder receives treatment, monitoring, or management of related infections or complications.",
