    "code": "D83.8",
    "rawCode": "D838",
    "shortDesc": "Other common variable immunodeficiencies",
    "longDesc": "Other common variable immunodeficiencies",
    "plainEnglish": "Common variable immunodeficiency (CVID) is a condition where your immune system doesn't make enough antibodies to fight infections effectively, leading to frequent or severe infections with bacteria, viruses, and sometimes fungi. This particular code refers to other forms of CVID that don't fit neatly into more specific categories—meaning your doctor has identified this immune deficiency but it may have unusual features or a less common presentation. You might experience recurring pneumonia, sinusitis, ear infections, or gastrointestinal infections, and your immune system may have trouble responding to vaccines.",
    "whoUses": "Immunologists and infectious disease specialists primarily use this code when diagnosing and managing patients with immunodeficiency disorders. It commonly appears on EOB statements for patients undergoing immunoglobulin replacement therapy, frequent infection evaluations, and immunological testing.",
