    "shortDesc": "Lymphocyte function antigen-1 [LFA-1] defect",
    "longDesc": "Lymphocyte function antigen-1 [LFA-1] defect",
    "plainEnglish": "This code describes a rare immune system disorder where your body produces defective LFA-1 proteins—special molecules that help immune cells (lymphocytes) stick to and interact with other cells to fight infections and disease. Without properly functioning LFA-1, your white blood cells can't effectively attack pathogens or communicate with other immune cells, leaving you vulnerable to frequent and severe infections starting in infancy or early childhood. This is an inherited genetic condition that requires specialized immune management and monitoring throughout life.",
    "whoUses": "Immunologists and pediatric specialists use this code to diagnose and manage patients with this rare primary immunodeficiency disorder. It rarely appears on routine patient EOB statements but is typically seen in specialized immunology clinics, academic medical centers, and genetic counseling records for affected families.",
