    "rawCode": "D841",
    "shortDesc": "Defects in the complement system",
    "longDesc": "Defects in the complement system",
    "plainEnglish": "Your immune system has a protein problem called a complement defect. Complement proteins are special molecules in your blood that help fight infections and clear damaged cells, but yours aren't working properly—either you don't have enough of them or they don't function correctly. This makes you more vulnerable to bacterial infections and certain autoimmune conditions because your immune system can't work as effectively as it should.",
    "whoUses": "Immunologists, rheumatologists, and infectious disease specialists use this code when diagnosing patients with suspected complement disorders, often after blood tests show low complement levels or abnormal function. This code rarely appears on patient EOB statements unless the patient has had specialized immunology testing and a confirmed diagnosis of a complement deficiency.",
