    "shortDesc": "Immunodeficiency due to conditions classified elsewhere",
    "longDesc": "Immunodeficiency due to conditions classified elsewhere",
    "plainEnglish": "This code describes a weakened immune system that has developed as a result of another existing medical condition. Rather than being caused by a genetic or primary immune disorder, your immune system is not functioning properly because of something else you have—such as an infection, cancer, autoimmune disease, or other systemic illness. This means your body's ability to fight off infections or diseases is compromised due to the underlying condition causing the immunodeficiency.",
    "whoUses": "Immunologists, infectious disease specialists, and primary care physicians use this code when documenting secondary immune system problems caused by other diagnosed conditions (such as HIV, lupus, or severe infections). It commonly appears on EOB statements for patients undergoing evaluation or treatment for weakened immunity that stems from another identified disease.",
