    "shortDesc": "Immunodeficiency due to external causes",
    "longDesc": "Immunodeficiency due to external causes",
    "plainEnglish": "This code describes a weakened immune system that has been caused by something external to your body—rather than by an inherited condition or internal disease. Common causes include chemotherapy or radiation treatments for cancer, long-term use of immunosuppressive medications (like those taken after organ transplants), malnutrition, or other external factors that damage your ability to fight infections. When your immune system is compromised this way, you become more susceptible to infections that a healthy immune system would normally handle easily.",
    "whoUses": "Oncologists, transplant surgeons, infectious disease specialists, and rheumatologists commonly use this code when treating patients whose immunity is suppressed by medical treatments or external circumstances. It appears on EOB statements fairly regularly for patients undergoing cancer treatment, those with organ transplants, or people on long-term immunosuppressive therapy.",
