    "plainEnglish": "Sarcoidosis of the lung is a condition where abnormal inflammatory nodules (small lumps) form in lung tissue, causing the lungs to scar and lose function over time. This happens when your immune system overreacts and creates these granulomas (clumps of inflamed cells) without a clear cause. Patients may experience shortness of breath, chronic cough, chest pain, and fatigue, though some people have no symptoms at all.",
    "whoUses": "Pulmonologists (lung specialists), rheumatologists, and internal medicine physicians commonly use this code when diagnosing and treating sarcoidosis. It frequently appears on patient EOBs in relation to chest imaging, pulmonary function tests, bronchoscopy procedures, and follow-up care visits.",
