    "shortDesc": "Sarcoidosis of lymph nodes",
    "longDesc": "Sarcoidosis of lymph nodes",
    "plainEnglish": "Sarcoidosis of the lymph nodes means your immune system is causing inflammation and forming tiny nodules (lumps) specifically in your lymph nodes throughout your body. Sarcoidosis is a condition where your immune system overreacts and creates these granules in various organs, but in this case it's primarily affecting the lymph nodes in your chest, neck, or abdomen. You might notice swollen lymph nodes, or this condition may only be discovered during imaging tests, and it can cause fatigue or shortness of breath if the lungs are involved.",
    "whoUses": "Pulmonologists, rheumatologists, and internal medicine physicians commonly diagnose and manage sarcoidosis of the lymph nodes, often after seeing characteristic findings on chest X-rays or CT scans. This code frequently appears on EOB statements when patients undergo imaging studies, biopsies, or specialist evaluations for lymphadenopathy of unknown cause.",
