    "plainEnglish": "Sarcoidosis is a condition where your immune system causes inflammation and creates small bumps (granulomas) in your lungs and lymph nodes, usually in your chest. When you have this diagnosis, both organs are affected at the same time, which can cause shortness of breath, chest pain, cough, and swollen lymph nodes. The exact cause isn't known, but your body's immune response is mistakenly attacking these tissues.",
    "whoUses": "Pulmonologists (lung specialists) and rheumatologists most commonly use this code when diagnosing and managing sarcoidosis in patients presenting with respiratory symptoms and imaging findings of both lung and lymph node involvement. This code appears on patient EOBs when they undergo chest imaging, pulmonary function tests, or biopsies to evaluate sarcoidosis.",
    "billable": true,
    "isNew": false,
    "isRevised": false,
