    "rawCode": "D8681",
    "shortDesc": "Sarcoid meningitis",
    "longDesc": "Sarcoid meningitis",
    "plainEnglish": "Sarcoid meningitis is an inflammation of the protective membranes that surround your brain and spinal cord (called the meninges) caused by sarcoidosis, a condition where your immune system creates small clumps of inflammatory cells in various parts of your body. When sarcoidosis affects the meninges, it can cause symptoms like severe headaches, fever, stiff neck, sensitivity to light, and potentially serious complications if left untreated. This is a relatively rare but serious manifestation of sarcoidosis that requires prompt diagnosis and treatment.",
    "whoUses": "Neurologists, infectious disease specialists, and rheumatologists commonly use this code when diagnosing and treating sarcoidosis affecting the central nervous system. This diagnosis may appear on an EOB if a patient requires hospitalization, lumbar puncture (spinal tap), MRI imaging, or specialized neurological consultation, though it is not frequently seen on routine outpatient claims.",
