    "longDesc": "Multiple cranial nerve palsies in sarcoidosis",
    "plainEnglish": "This code describes a complication of sarcoidosis—an inflammatory disease that can affect multiple organs—where the inflammation damages several of the cranial nerves (the 12 pairs of nerves that control movement and sensation in your face and head). When these nerves are damaged, you may experience weakness or paralysis of facial muscles, difficulty with eye movements, trouble swallowing, or hearing problems, depending on which nerves are affected. This condition requires specialized treatment to control the underlying sarcoidosis and prevent permanent nerve damage.",
    "whoUses": "Neurologists, pulmonologists, and rheumatologists typically use this code when diagnosing and managing sarcoidosis patients who develop cranial nerve involvement. This code appears on EOB statements for patients undergoing neurological evaluations, imaging studies, or specialist consultations related to this complication, though it's a relatively rare manifestation of sarcoidosis.",
