    "shortDesc": "Sarcoid iridocyclitis",
    "longDesc": "Sarcoid iridocyclitis",
    "plainEnglish": "Sarcoid iridocyclitis means your iris and ciliary body (the parts inside your eye that control focus and produce fluid) are inflamed because of sarcoidosis, a condition where your immune system creates abnormal nodules (lumps) throughout your body. This eye inflammation can cause pain, redness, blurred vision, light sensitivity, and floaters, and if left untreated, can lead to complications like cataracts or glaucoma. It's a sign that sarcoidosis is affecting your eyes, even if you don't have obvious lung or skin symptoms.",
    "whoUses": "Ophthalmologists and rheumatologists primarily use this code when treating sarcoidosis patients with eye involvement. While it may appear on EOB statements for patients receiving eye exams or treatment related to their sarcoidosis, it's less common on routine patient bills compared to other eye conditions, since many patients with sarcoidosis never develop ocular complications.",
