    "plainEnglish": "Sarcoid pyelonephritis is a kidney infection caused by sarcoidosis, a rare inflammatory disease where granulomas (small inflammatory nodules) form in various organs including the kidneys. This condition means the kidneys are inflamed and infected due to sarcoidosis deposits, which can cause fever, back or side pain, cloudy urine, and difficulty urinating. It's a serious complication that requires treatment to prevent permanent kidney damage.",
    "whoUses": "Nephrologists (kidney specialists) and rheumatologists diagnose and manage this condition, often in consultation with pulmonologists since sarcoidosis typically affects the lungs first. This code appears on EOB statements when sarcoidosis has progressed to involve the kidneys, though it is relatively uncommon compared to other causes of pyelonephritis.",
