    "shortDesc": "Sarcoid myocarditis",
    "longDesc": "Sarcoid myocarditis",
    "plainEnglish": "Sarcoid myocarditis is inflammation of the heart muscle caused by sarcoidosis, a disease where abnormal clumps of cells form in various organs throughout the body. When sarcoidosis affects the heart specifically, it can cause chest pain, irregular heartbeats, shortness of breath, or even heart failure if the inflammation is severe. This is a serious condition because the inflamed heart muscle may not pump blood effectively, potentially leading to dangerous arrhythmias or reduced heart function.",
    "whoUses": "Cardiologists and rheumatologists diagnose and treat sarcoid myocarditis, often using imaging tests like cardiac MRI and PET scans to detect the inflammation. This code commonly appears on EOBs for patients undergoing cardiac workup, imaging studies, or specialized cardiology consultations when sarcoidosis is suspected or confirmed to involve the heart.",
