    "plainEnglish": "Sarcoid arthropathy is joint pain and inflammation caused by sarcoidosis, a systemic disease in which your immune system produces abnormal inflammatory cells that can affect multiple organs throughout your body. When sarcoidosis affects your joints, you may experience swelling, stiffness, and discomfort, particularly in the ankles, knees, wrists, and hands. This occurs because the same inflammatory process that creates granulomas (small collections of immune cells) in the lungs and other organs can also damage the joints.",
    "whoUses": "Rheumatologists, pulmonologists, and internal medicine doctors use this code when treating patients whose sarcoidosis has manifested as joint disease. It commonly appears on EOB statements for patients undergoing imaging, lab work, or treatment for sarcoidosis-related joint symptoms, often alongside respiratory or systemic sarcoidosis codes.",
