    "whoUses": "Rheumatologists, pulmonologists, and internists use this code when diagnosing sarcoidosis patients who develop muscle involvement. It may appear on EOB statements for patients undergoing muscle biopsies, imaging studies, or specialty care related to systemic sarcoidosis, though it's relatively uncommon since most sarcoidosis cases don't involve muscular inflammation.",
