    "shortDesc": "Sarcoidosis of other sites",
    "longDesc": "Sarcoidosis of other sites",
    "plainEnglish": "Sarcoidosis is a rare inflammatory disease where your body forms abnormal clumps of cells (called granulomas) in various organs, and this code indicates the sarcoidosis is affecting parts of your body beyond the lungs, skin, or other more commonly involved areas. These clumps can develop in organs like the liver, kidney, heart, nervous system, or other tissues, causing inflammation and potentially affecting how those organs work. You may experience symptoms depending on which organs are involved, ranging from no symptoms at all to fatigue, fever, weight loss, or specific problems related to the affected organ.",
    "whoUses": "Pulmonologists, rheumatologists, cardiologists, hepatologists, and neurologists use this code when diagnosing and treating sarcoidosis affecting less common sites. This code commonly appears on EOB statements for patients undergoing diagnostic testing (biopsies, imaging, blood work) or specialist consultation visits related to multi-system sarcoidosis.",
