    "shortDesc": "Sarcoidosis, unspecified",
    "longDesc": "Sarcoidosis, unspecified",
    "plainEnglish": "Sarcoidosis is a chronic inflammatory disease where your immune system creates tiny clumps of cells (granulomas) that can affect various organs—most commonly the lungs and lymph nodes, but also the skin, eyes, heart, and other areas. The \"unspecified\" part means your doctor has diagnosed you with sarcoidosis but hasn't documented which specific organs are involved or the type of sarcoidosis you have. Symptoms vary widely depending on which organs are affected and can include shortness of breath, chest pain, fatigue, skin rashes, or eye problems.",
    "whoUses": "Pulmonologists (lung specialists) and rheumatologists most commonly use this code, as they manage sarcoidosis cases. This code appears regularly on patient EOB statements when sarcoidosis is confirmed but the specific organ involvement hasn't been clearly specified in the medical record.",
