    "rawCode": "D891",
    "shortDesc": "Cryoglobulinemia",
    "longDesc": "Cryoglobulinemia",
    "plainEnglish": "Cryoglobulinemia is a rare immune system disorder where abnormal proteins in your blood solidify and clump together when exposed to cold temperatures, then dissolve again when warmed. This can cause inflammation and damage to small blood vessels, leading to symptoms like joint pain, numbness or tingling in your fingers and toes, skin rashes (especially on lower legs), and in severe cases, organ damage. The condition may develop on its own or occur alongside other diseases like hepatitis C or certain cancers.",
    "whoUses": "Rheumatologists, hematologists, and immunologists use this code when diagnosing and managing cryoglobulinemia, often in consultation with hepatologists if liver disease is involved. This code commonly appears on EOB statements for patients undergoing testing (blood work, imaging) and treatment for this condition, though it's relatively uncommon compared to other autoimmune disorders.",
