    "code": "D89.41",
    "rawCode": "D8941",
    "shortDesc": "Monoclonal mast cell activation syndrome",
    "longDesc": "Monoclonal mast cell activation syndrome",
    "plainEnglish": "This diagnosis means you have a condition where mast cells (immune cells in your body) are overactive and release too many chemical messengers like histamine, causing various symptoms. This specific form is caused by a single clone of abnormal mast cells, which can lead to symptoms like flushing, itching, abdominal pain, diarrhea, or anaphylaxis-like reactions. Unlike typical allergies, these symptoms occur without a clear trigger because the mast cells are inherently unstable.",
    "whoUses": "This code is primarily used by allergists/immunologists and hematologists who specialize in mast cell disorders and bone marrow conditions. It appears on EOB statements when a patient has been evaluated for or diagnosed with this rare condition, though it is not commonly seen in typical medical encounters.",
