    "rawCode": "D8982",
    "shortDesc": "Autoimmune lymphoproliferative syndrome [ALPS]",
    "longDesc": "Autoimmune lymphoproliferative syndrome [ALPS]",
    "plainEnglish": "Autoimmune lymphoproliferative syndrome (ALPS) is a rare immune system disorder where your body cannot properly control the death of certain white blood cells (lymphocytes), causing them to accumulate abnormally in your lymph nodes, spleen, and liver. This buildup leads to enlargement of these organs and causes your immune system to mistakenly attack your own healthy cells, resulting in symptoms like swollen lymph nodes, an enlarged spleen and liver, and sometimes anemia or low platelet counts. The condition is usually present from birth or early childhood, though symptoms may appear at various ages.",
    "whoUses": "Immunologists, hematologists, and pediatricians diagnose and manage ALPS, often working with genetic specialists since it's an inherited disorder. This code appears on EOBs when patients undergo diagnostic testing (flow cytometry, genetic testing) or receive specialist consultations and ongoing treatment for immune management.",
