    "plainEnglish": "Cytokine release syndrome (CRS) is a serious immune system reaction where your body releases too many inflammatory chemicals called cytokines, usually triggered by certain cancer treatments like CAR-T cell therapy or immunotherapies. Grade 1 is the mildest severity level, meaning you may experience mild symptoms like fever, fatigue, or mild body aches, but they are manageable and not life-threatening. This condition typically resolves on its own or with supportive care like fluids and rest.",
